import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.axes import Axes
from statsmodels.tsa.arima.model import ARIMA
from typing import List, Tuple


def task_func(df: pd.DataFrame) -> Tuple[List[float], Axes]:
    fig, ax = plt.subplots(figsize=(10, 5))
    horizon = 7

    def _empty_plot(message: str, fallback: float = 0.0) -> Tuple[List[float], Axes]:
        ax.set_title("7-Day ARIMA Forecast")
        ax.text(0.5, 0.5, message, ha="center", va="center", transform=ax.transAxes)
        ax.set_axis_off()
        fig.tight_layout()
        return [fallback] * horizon, ax

    if df is None or df.empty:
        return _empty_plot("No data available", 0.0)

    columns = list(df.columns)

    def _find_column(keyword: str):
        for col in columns:
            if keyword in str(col).strip().lower():
                return col
        return None

    # Identify the closing-price column.
    close_col = None
    for col in columns:
        if str(col).strip().lower() == "close":
            close_col = col
            break
    if close_col is None:
        close_col = _find_column("close")
    if close_col is None:
        numeric_cols = df.select_dtypes(include="number").columns.tolist()
        if numeric_cols:
            close_col = numeric_cols[-1]
        else:
            for col in reversed(columns):
                if pd.to_numeric(df[col], errors="coerce").notna().any():
                    close_col = col
                    break

    if close_col is None:
        return _empty_plot("No numeric price column found", 0.0)

    # Identify a date-like column if present.
    date_col = None
    for col in columns:
        name = str(col).strip().lower()
        if name in {"date", "datetime", "time", "timestamp"} or "date" in name or "time" in name:
            date_col = col
            break

    working = df.copy()

    if date_col is not None:
        working[date_col] = pd.to_datetime(working[date_col], errors="coerce")
    working[close_col] = pd.to_numeric(working[close_col], errors="coerce")

    subset_cols = [close_col]
    if date_col is not None:
        subset_cols = [date_col, close_col]

    working = working[subset_cols].dropna(subset=[close_col] + ([date_col] if date_col is not None else []))

    if working.empty:
        return _empty_plot("No valid price data available", 0.0)

    if date_col is not None:
        working = working.sort_values(date_col)
        series = working.set_index(date_col)[close_col].astype(float)
    elif isinstance(df.index, pd.DatetimeIndex):
        series = working[close_col].astype(float).copy()
        series.index = pd.to_datetime(working.index)
        series = series.sort_index()
    else:
        series = working[close_col].astype(float)

    if series.empty:
        return _empty_plot("No valid price data available", 0.0)

    # Fit ARIMA and forecast.
    forecast: List[float]
    if len(series) < 2:
        forecast = [float(series.iloc[-1])] * horizon
    else:
        forecast = []
        candidate_orders = [(1, 1, 0), (1, 1, 1), (0, 1, 0)]
        for order in candidate_orders:
            try:
                model = ARIMA(
                    series,
                    order=order,
                    enforce_stationarity=False,
                    enforce_invertibility=False,
                )
                fitted = model.fit()
                preds = fitted.forecast(steps=horizon)
                forecast = [float(x) for x in preds]
                break
            except Exception:
                continue
        if not forecast:
            forecast = [float(series.iloc[-1])] * horizon

    # Plot history and forecast.
    if isinstance(series.index, pd.DatetimeIndex):
        hist_x = series.index
        last_date = hist_x.max()
        future_x = pd.date_range(start=last_date + pd.Timedelta(days=1), periods=horizon, freq="D")
        ax.plot(hist_x, series.values, label="Historical Prices", color="tab:blue")
        ax.plot(future_x, forecast, label="ARIMA Forecast", color="tab:orange", marker="o")
    else:
        hist_x = list(range(len(series)))
        future_x = list(range(len(series), len(series) + horizon))
        ax.plot(hist_x, series.values, label="Historical Prices", color="tab:blue")
        ax.plot(future_x, forecast, label="ARIMA Forecast", color="tab:orange", marker="o")

    ax.set_title("7-Day ARIMA Forecast")
    ax.set_xlabel("Date" if isinstance(series.index, pd.DatetimeIndex) else "Observation")
    ax.set_ylabel("Closing Price")
    ax.grid(True, alpha=0.3)
    ax.legend()
    fig.tight_layout()

    return forecast, ax
